import type { CourseUnitTestConfig, UnitDef, UnitPoolQuestion } from '@/lib/unit-tests/engine'

/**
 * PSAT/NMSQT unit tests.
 *
 * Units mirror the eight College Board domains of the digital PSAT (2024+):
 * four in Reading & Writing, four in Math. Questions are written at PSAT
 * difficulty — the same skills as the SAT but a lower ceiling (no advanced
 * trigonometry, lighter algebra 2) — rather than reused from the SAT bank, so
 * the two tracks stay distinct.
 *
 * Each unit carries 48 questions so all four 12-question variants are fully
 * distinct.
 */
const q = (domain: string, topicSlug: string, question: string, options: string[], explanation: string): UnitPoolQuestion =>
  ({ domain, topicSlug, question, options, correctAnswer: 0, explanation })

const info = (t: string, a: string, o: string[], e: string) => q('information-ideas', t, a, o, e)
const craft = (t: string, a: string, o: string[], e: string) => q('craft-structure', t, a, o, e)
const expr = (t: string, a: string, o: string[], e: string) => q('expression-ideas', t, a, o, e)
const conv = (t: string, a: string, o: string[], e: string) => q('standard-conventions', t, a, o, e)
const alg = (t: string, a: string, o: string[], e: string) => q('algebra-psat', t, a, o, e)
const adv = (t: string, a: string, o: string[], e: string) => q('advanced-math-psat', t, a, o, e)
const data = (t: string, a: string, o: string[], e: string) => q('problem-solving-data', t, a, o, e)
const geo = (t: string, a: string, o: string[], e: string) => q('geometry-trig-psat', t, a, o, e)

